const STAGE_HTML = `<div class="layer" id="bg">
    <div class="glow" id="glowG"></div>
    <div class="glow" id="glowR"></div>
    <div class="layer" id="grid"></div>
    <div class="layer" id="dots"></div>
  </div>
  <div class="layer" id="fx"></div>
  <div class="layer" id="vignette"></div>`;

/** Builds the scene inside `stage` and returns { render(t), DURATION, ready }. */
function buildScene(stage) {
  const $ = (id) => stage.querySelector("#" + id);
  const fx = $("fx");
  const W = 1080, H = 1920, CX = 540;

  // ── math ────────────────────────────────────────────────────────────
  const cl = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
  const lerp = (a, b, k) => a + (b - a) * k;
  const p = (t, s, d) => cl((t - s) / d);
  const eo = (x) => 1 - Math.pow(1 - x, 3);
  const eio = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  const ei = (x) => x * x * x;
  const back = (x) => (x <= 0 ? 0 : x >= 1 ? 1 : 1 + 2.4 * Math.pow(x - 1, 3) + 1.4 * Math.pow(x - 1, 2));
  function rng(seed) { return () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }

  const ic = (n, size, color = "#fff", sw = 2.2, fill = "none") =>
    `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="${fill}" stroke="${color}" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round">${ICONS[n]}</svg>`;

  // ── element registry ───────────────────────────────────────────────
  const anims = [];
  const subs = [];
  function A(html, fn, cls = "", parent = fx) {
    const d = document.createElement("div");
    d.className = "a " + cls;
    d.innerHTML = html;
    parent.appendChild(d);
    anims.push({ d, fn });
    return d;
  }
  function apply(d, s) {
    if (!s || s.o <= 0.002) { d.style.display = "none"; return; }
    d.style.display = "";
    d.style.opacity = s.o;
    d.style.transform = `translate(${s.x}px, ${s.y}px) translate(-50%, -50%) rotate(${s.r || 0}deg) scale(${s.s ?? 1})`;
    d.style.filter = s.b > 0.05 ? `blur(${s.b}px)` : "none";
  }

  /** A line of text whose words rise in one after another, and leave together. */
  function headline(text, o) {
    const { y, size = 88, start, end, color = "#fff", hl = [], weight = 900, out = 0.35, x = CX } = o;
    const words = text.split(" ");
    // "|" marks where a long line breaks, so it breaks between phrases rather than wherever it runs out of room.
    const html = words.map((w) => (w === "|" ? "<br>" : `<span class="w ${hl.includes(w) ? "acc" : ""}">${w}</span>`)).join(" ");
    const d = A(`<div class="h" style="font-size:${size}px;color:${color};font-weight:${weight}">${html}</div>`, (t) => {
      if (t < start - 0.05 || t > end + out) return null;
      const k = eio(p(t, end, out));
      const dim = o.dimAt ? lerp(1, o.dimTo ?? 0.45, eo(p(t, o.dimAt, 0.4))) : 1;
      return { x, y: y - k * 50, o: (1 - k) * dim, b: k * 14, s: 1 - k * 0.04 };
    });
    const spans = [...d.querySelectorAll(".w")];
    subs.push((t) => spans.forEach((sp, i) => {
      const k = eo(p(t, start + i * 0.09, 0.5));
      sp.style.opacity = k;
      sp.style.transform = `translateY(${(1 - k) * 60}px)`;
      sp.style.filter = k < 0.98 ? `blur(${(1 - k) * 12}px)` : "none";
    }));
    return d;
  }

  // ── background ─────────────────────────────────────────────────────
  const dotsEl = $("dots");
  const R = rng(7);
  const dots = Array.from({ length: 42 }, () => {
    const d = document.createElement("div"); d.className = "dot"; dotsEl.appendChild(d);
    return { d, x: R() * W, y: R() * H, v: 20 + R() * 50, s: 0.4 + R() * 1.2, ph: R() * 6.28 };
  });
  const glowG = $("glowG"), glowR = $("glowR"), grid = $("grid");

  function bg(t) {
    const chaos = p(t, 3.2, 0.8) * (1 - p(t, 9.8, 0.5));
    glowG.style.opacity = (1 - chaos * 0.85) * (0.85 + 0.15 * Math.sin(t * 1.3));
    glowG.style.transform = `translate(${Math.sin(t * 0.4) * 60}px, ${180 + Math.cos(t * 0.33) * 80}px)`;
    glowR.style.opacity = chaos * 0.9;
    glowR.style.transform = `translate(${Math.cos(t * 0.5) * 80}px, ${300 + Math.sin(t * 0.45) * 100}px)`;
    grid.style.backgroundPosition = `0px ${(t * 22) % 54}px`;
    grid.style.opacity = 0.9 - chaos * 0.4;
    for (const q of dots) {
      const y = ((q.y - t * q.v) % H + H) % H;
      q.d.style.transform = `translate(${q.x + Math.sin(t * 0.8 + q.ph) * 14}px, ${y}px) scale(${q.s})`;
      q.d.style.opacity = (0.15 + 0.35 * (0.5 + 0.5 * Math.sin(t * 2 + q.ph))) * (1 - chaos * 0.7);
      q.d.style.background = chaos > 0.5 ? "#9aa59f" : "#2ee6a0";
    }
  }

  // ═══ Scene 1 — the search (0 – 3.4) ══════════════════════════════════
  A(`<div class="qmark">؟</div>`, (t) => {
    if (t > 3.6) return null;
    const k = eo(p(t, 0, 1.2)), out = p(t, 3.0, 0.5);
    return { x: CX + 40, y: 860, o: k * (1 - out), r: -8 + t * 3, s: 0.9 + t * 0.04 };
  });

  const Q = "تبحث عن فرصة في الإعلام؟";
  const bar = A(`<div class="search"><div class="sicon">${ic("search", 52, "#fff", 2.6)}</div><div class="stext"><span id="typed"></span><span class="caret" id="caret"></span></div></div>`, (t) => {
    if (t > 3.5) return null;
    const k = back(p(t, 0.05, 0.6)), out = eio(p(t, 3.0, 0.4));
    const shake = t > 2.55 && t < 2.95 ? Math.sin(t * 90) * 10 * (1 - p(t, 2.55, 0.4)) : 0;
    return { x: CX + shake, y: 860 - out * 40, o: cl(k) * (1 - out), s: 0.8 + 0.2 * k - out * 0.08, b: out * 12 };
  });
  const typed = bar.querySelector("#typed"), caret = bar.querySelector("#caret");
  subs.push((t) => {
    const n = Math.round(Q.length * cl((t - 0.5) / 1.5));
    typed.textContent = Q.slice(0, n);
    caret.style.opacity = Math.floor(t * 3.2) % 2 === 0 || (t > 0.5 && t < 2.0) ? 1 : 0;
  });

  const drop = A(`<div class="drop">${[78, 56, 68].map((w) => `<div class="skel" style="width:${w}%"><i></i></div>`).join("")}</div>`, (t) => {
    if (t < 1.9 || t > 3.5) return null;
    const k = eo(p(t, 2.0, 0.45)), out = eio(p(t, 3.0, 0.4));
    return { x: CX, y: 1075 + (1 - k) * -40 - out * 40, o: k * (1 - out), b: out * 12 };
  });
  const shimmers = [...drop.querySelectorAll(".skel i")];
  subs.push((t) => shimmers.forEach((s, i) => { s.style.left = `${(((t * 1.4 + i * 0.2) % 1.4) / 1.4) * 160 - 50}%`; }));

  // ═══ Scene 2 — the chaos (3.4 – 7.7) ════════════════════════════════
  headline("صفحاتٌ مهجورة…", { y: 430, start: 3.4, end: 4.6, size: 100 });
  headline("إعلاناتٌ منتهية…", { y: 430, start: 4.75, end: 6.0, size: 100 });
  headline("ومجموعاتٌ لا تنتهي.", { y: 430, start: 6.15, end: 7.55, size: 100 });

  /** Everything chaotic is pulled into the centre and gone at 9.6 – 10.1. */
  function collapse(s, t) {
    if (!s) return s;
    const k = ei(p(t, 9.55, 0.5));
    if (k >= 1) return null;
    return { ...s, x: lerp(s.x, CX, k), y: lerp(s.y, 960, k), s: (s.s ?? 1) * (1 - k * 0.95), r: (s.r || 0) + k * 120, o: s.o * (1 - k * 0.3) };
  }
  /** Restless motion that grows as the crowd thickens. */
  const jitter = (t, ph, base = 6) => {
    const amp = base + 14 * p(t, 7.7, 1.2);
    return { jx: Math.sin(t * 2.3 + ph) * amp, jy: Math.cos(t * 1.9 + ph * 1.7) * amp };
  };

  const webSvg = `<svg class="web" viewBox="0 0 100 100" fill="none" stroke="#fff" stroke-width="1.5"><path d="M0 0 L100 100 M0 0 L100 40 M0 0 L40 100 M0 0 L100 0 M0 0 L0 100"/><path d="M30 0 Q22 22 0 30 M60 0 Q45 45 0 60 M90 0 Q68 68 0 90"/></svg>`;
  A(`<div class="card pg">${webSvg}<div class="cover"></div><div class="row"><div class="av">${ic("radio", 60, "#6b746f")}</div><div class="nm">صفحة فرص الإعلام</div></div>
     <div class="meta">${ic("clock", 36, "#7d8781")} آخر منشور: منذ 3 سنوات</div><div class="lines"><div style="width:90%"></div><div style="width:70%"></div></div></div>`, (t) => {
    if (t < 3.45) return null;
    const k = back(p(t, 3.5, 0.55)), mv = eio(p(t, 4.7, 0.6));
    const flick = t < 4.7 ? 0.8 + 0.2 * Math.abs(Math.sin(t * 13)) : 0.85;
    const { jx, jy } = jitter(t, 1.1);
    return collapse({ x: lerp(CX, 300, mv) + jx * mv, y: lerp(930, 1330, mv) + jy * mv, o: cl(k * 1.4) * flick, s: lerp(0.6 + 0.4 * k, 0.66, mv), r: lerp(0, -9, mv) }, t);
  });

  A(`<div class="card ad"><div class="tag">${ic("briefcase", 30, "#a3aea7")} إعلان توظيف</div><div class="ttl">مطلوب مقدّم أخبار</div>
     <div class="dl">${ic("clock", 34, "#8b958f")} آخر أجل: 12 مارس 2021</div><div class="stamp" id="stamp">انتهى</div></div>`, (t) => {
    if (t < 4.75) return null;
    const k = back(p(t, 4.8, 0.55)), mv = eio(p(t, 6.0, 0.6));
    const { jx, jy } = jitter(t, 2.7);
    return collapse({ x: lerp(CX, 760, mv) + jx * mv, y: lerp(920, 1520, mv) + jy * mv, o: cl(k * 1.4), s: lerp(0.6 + 0.4 * k, 0.64, mv), r: lerp(0, 8, mv) }, t);
  });
  const stamp = $("stamp");
  subs.push((t) => {
    const k = p(t, 5.3, 0.22);
    stamp.style.opacity = k > 0 ? 1 : 0;
    stamp.style.transform = `rotate(-14deg) scale(${lerp(2.4, 1, eo(k))})`;
  });

  const groups = [
    ["فرص إعلامية DZ", "+99"], ["صحفيون جزائريون", "245"], ["وظائف الإعلام", "1.2k"], ["مونتاج وتصوير", "87"],
    ["إذاعات الجزائر", "312"], ["مجموعة المعلّقين", "56"], ["عروض عمل الإعلام", "+99"], ["طلبة الإعلام", "640"],
    ["قنوات وفرص", "128"], ["مذيعون ومقدّمون", "73"], ["فرص التدريب", "410"], ["إعلام وتواصل", "2.3k"],
    ["كتّاب المحتوى", "95"], ["مصوّرون محترفون", "188"],
  ];
  const RB = rng(42);
  function bubble(name, count, x, y, start, seed) {
    const r = (RB() - 0.5) * 14, ph = RB() * 6.28;
    A(`<div class="bub"><div class="ba">${ic("users", 36, "#9aa59f")}</div><div class="bn">${name}</div><div class="bc">${count}</div></div>`, (t) => {
      if (t < start) return null;
      const k = back(p(t, start, 0.38));
      const { jx, jy } = jitter(t, ph, 5);
      return collapse({ x: x + jx, y: y + jy, o: cl(k * 1.6), s: 0.4 + 0.6 * k, r }, t);
    });
  }
  groups.forEach(([n, c], i) => {
    const col = i % 2, row = Math.floor(i / 2);
    const x = (col ? 330 : 740) + (RB() - 0.5) * 180;
    const y = 660 + row * 130 + (RB() - 0.5) * 60;
    bubble(n, c, x, y, 6.2 + i * 0.085, i);
  });

  // ═══ Scene 3 — the opportunity lost in the crowd (7.7 – 10.1) ════════
  headline("والفرصة ضائعة | في الزحام.", { y: 430, start: 7.7, end: 9.45, size: 96, hl: ["والفرصة"] });

  A(`<div class="opp">${ic("sparkles", 50, "#fff", 2.4)} فرصة عمل حقيقية</div>`, (t) => {
    if (t < 7.85) return null;
    const k = back(p(t, 7.9, 0.5)), lost = eio(p(t, 8.5, 0.9));
    return collapse({ x: CX, y: 1080, o: cl(k * 1.5) * lerp(1, 0.25, lost), s: (0.5 + 0.5 * k) * lerp(1, 0.72, lost) }, t);
  });
  const noise = [["رسائل غير مقروءة", "3.4k"], ["منشورات قديمة", "999"], ["روابط معطّلة", "41"], ["إعلانات مكررة", "+99"],
    ["مجموعة جديدة", "12"], ["تنبيهات", "530"], ["طلبات انضمام", "77"], ["رسائل مزعجة", "1.8k"]];
  noise.forEach(([n, c], i) => {
    const ang = (i / noise.length) * Math.PI * 2 + 0.4;
    const x = CX + Math.cos(ang) * (150 + RB() * 90);
    const y = 1080 + Math.sin(ang) * (120 + RB() * 140);
    bubble(n, c, x, y, 8.45 + i * 0.07, 100 + i);
  });

  const flash = A(``, (t) => {
    if (t < 9.9 || t > 10.8) return null;
    const k = p(t, 9.9, 0.18), out = p(t, 10.08, 0.7);
    return { x: CX, y: 960, o: eo(k) * (1 - eo(out)), s: 1 };
  }, "");
  flash.innerHTML = `<div class="flash" style="position:static;width:1400px;height:1400px;border-radius:50%"></div>`;

  // ═══ Scene 4 — Sanad (10.1 – 12.6) ═══════════════════════════════════
  [0, 1, 2].forEach((i) => A(`<div class="ring"></div>`, (t) => {
    const st = 10.15 + i * 0.28;
    if (t < st || t > st + 1.6) return null;
    const k = eo(p(t, st, 1.6));
    return { x: CX, y: 840, o: (1 - k) * 0.9, s: 0.55 + k * 1.9 };
  }));
  A(`<img class="logoimg" src="${ICON_SRC}" style="width:420px;height:420px" />`, (t) => {
    if (t < 10.1 || t > 12.9) return null;
    const k = back(p(t, 10.12, 0.7)), out = eio(p(t, 12.25, 0.5));
    const bob = Math.sin(t * 2.4) * 8;
    return { x: CX, y: 840 + bob - out * 160, o: cl(k * 1.6) * (1 - out), s: (0.3 + 0.7 * k) * (1 - out * 0.4), r: (1 - cl(k)) * -25 };
  });
  const wm = A(`<img class="logoimg" src="${LOGO_SRC}" style="width:680px;filter:drop-shadow(0 0 40px rgba(46,230,160,0.45))" />`, (t) => {
    if (t < 10.6 || t > 23.7) return null;
    const mv = eio(p(t, 12.3, 0.55)), out = eio(p(t, 23.3, 0.35));
    return { x: CX, y: lerp(1150, 290, mv), o: 1 - out, s: lerp(1, 0.52, mv), b: out * 10 };
  });
  const wmImg = wm.querySelector("img");
  subs.push((t) => {
    const k = eo(p(t, 10.65, 0.7));
    wmImg.style.clipPath = `inset(0 0 0 ${(1 - k) * 100}%)`;
  });

  // ═══ Scene 5 — one platform (12.6 – 16.8) ════════════════════════════
  headline("منصةٌ واحدة تجمع لك", { y: 520, start: 12.7, end: 16.45, size: 90, hl: ["واحدة"] });
  const feats = [
    ["briefcase", "عروض التوظيف", "مذيع · محرر · مونتير · مصوّر", "جديد"],
    ["graduation-cap", "الدورات", "تكوين مع محترفين في الميدان", "سجّل"],
    ["trophy", "المسابقات", "جوائز وفرص للظهور", "شارك"],
  ];
  feats.forEach(([icon, title, sub, badge], i) => {
    const st = 13.2 + i * 0.45, y = 790 + i * 225, dir = i % 2 ? -1 : 1;
    const d = A(`<div class="feat"><div class="ftile">${ic(icon, 66, "#fff", 2.2)}</div><div><div class="ftitle">${title}</div><div class="fsub">${sub}</div></div><div class="fbadge">${badge}</div></div>`, (t) => {
      if (t < st || t > 16.9) return null;
      const k = eo(p(t, st, 0.6)), out = eio(p(t, 16.35 + i * 0.06, 0.4));
      return { x: CX + (1 - k) * 420 * dir + out * -380 * dir, y, o: cl(k * 1.3) * (1 - out), b: (1 - k) * 10 + out * 10 };
    });
    const b = d.querySelector(".fbadge");
    subs.push((t) => { const k = back(p(t, st + 0.55, 0.4)); b.style.opacity = cl(k * 1.5); b.style.transform = `scale(${0.3 + 0.7 * k})`; });
  });

  // ═══ Scene 6 — your work, on show (16.8 – 19.6) ══════════════════════
  headline("ومساحةً تعرض | فيها أعمالك.", { y: 520, start: 16.85, end: 19.3, size: 88, hl: ["أعمالك."] });
  const fmt = (n) => (n >= 1000 ? (n / 1000).toFixed(1) + "k" : String(Math.round(n)));
  const works = [
    { title: "تقرير مصوّر", bg: "linear-gradient(135deg,#0f5132,#00a355)", kind: "video", likes: 128, views: 2400 },
    { title: "تعليق صوتي", bg: "linear-gradient(135deg,#123a5c,#1f8a70)", kind: "audio", likes: 96, views: 1800 },
    { title: "صور ميدانية", bg: "linear-gradient(135deg,#3b2a12,#b7791f)", kind: "photo", likes: 214, views: 3100 },
    { title: "مقال رأي", bg: "linear-gradient(135deg,#2a1748,#6b46c1)", kind: "article", likes: 73, views: 950 },
  ];
  works.forEach((w, i) => {
    const col = i % 2, row = Math.floor(i / 2);
    const x = col ? 320 : 760, y = 880 + row * 440, st = 17.15 + i * 0.2;
    const inner =
      w.kind === "video" ? `<div class="pbtn">${ic("play", 52, "#006233", 2.4, "#006233")}</div>`
      : w.kind === "audio" ? `<div class="wave">${Array.from({ length: 13 }, () => "<i></i>").join("")}</div>`
      : w.kind === "photo" ? ic("camera", 110, "#fff", 1.8)
      : ic("file-text", 110, "#fff", 1.8);
    const d = A(`<div class="work"><div class="thumb" style="background:${w.bg}">${inner}</div><div class="wbody"><div class="wtitle">${w.title}</div>
       <div class="wmeta"><span>${ic("heart", 34, "#ff5a7a", 2.4, "#ff5a7a")}<b class="lk">0</b></span><span>${ic("eye", 34, "#a9cdb8")}<b class="vw">0</b></span></div></div></div>`, (t) => {
      if (t < st || t > 19.7) return null;
      const k = back(p(t, st, 0.55)), out = eio(p(t, 19.25 + i * 0.04, 0.35));
      return { x, y: y + (1 - cl(k)) * 80, o: cl(k * 1.4) * (1 - out), s: (0.7 + 0.3 * k) * (1 - out * 0.1), b: out * 10 };
    });
    const lk = d.querySelector(".lk"), vw = d.querySelector(".vw"), bars = [...d.querySelectorAll(".wave i")];
    subs.push((t) => {
      const k = eo(p(t, st + 0.3, 1.6));
      lk.textContent = fmt(w.likes * k); vw.textContent = fmt(w.views * k);
      bars.forEach((b, j) => { b.style.height = `${30 + 100 * Math.abs(Math.sin(t * 6 + j * 0.7))}px`; });
    });
    // hearts drifting up from the card
    for (let h = 0; h < 2; h++) {
      const hs = 17.9 + i * 0.25 + h * 0.6, hx = x + (RB() - 0.5) * 200;
      A(ic("heart", 46, "#ff5a7a", 2, "#ff5a7a"), (t) => {
        if (t < hs || t > hs + 1.3) return null;
        const k = p(t, hs, 1.3);
        return { x: hx + Math.sin(k * 6) * 20, y: y - 60 - k * 260, o: Math.sin(k * Math.PI), s: 0.6 + k * 0.6 };
      });
    }
  });

  // ═══ Scene 7 — more (19.6 – 23.6) ════════════════════════════════════
  const kin = [["فرصٌ أكثر…", 19.7], ["تدريبٌ أكثر…", 20.55], ["تواصلٌ أكثر…", 21.4]];
  kin.forEach(([txt, st], i) =>
    headline(txt, { y: 640 + i * 165, start: st, end: 23.3, size: 112, hl: ["أكثر…"], dimAt: kin[i + 1]?.[1] ?? 22.25, dimTo: 0.5 }));
  headline("وسندٌ لك.", { y: 1200, start: 22.3, end: 23.3, size: 170, hl: ["وسندٌ", "لك."] });
  const sw = A(`<svg class="swoosh" viewBox="0 0 620 70" fill="none"><path id="swp" d="M600 40 C 450 10, 200 70, 20 30" stroke="url(#sg)" stroke-width="12" stroke-linecap="round"/>
    <defs><linearGradient id="sg" x1="0" x2="1"><stop offset="0" stop-color="#00a355"/><stop offset="1" stop-color="#2ee6a0"/></linearGradient></defs></svg>`, (t) => {
    if (t < 22.5 || t > 23.7) return null;
    const out = eio(p(t, 23.3, 0.35));
    return { x: CX, y: 1340 - out * 50, o: 1 - out, b: out * 12 };
  });
  const swp = sw.querySelector("#swp");
  subs.push((t) => { const L = 640; swp.style.strokeDasharray = L; swp.style.strokeDashoffset = L * (1 - eo(p(t, 22.6, 0.5))); });

  // ═══ Scene 8 — sign-off (23.6 – end) ═════════════════════════════════
  [0, 1].forEach((i) => A(`<div class="ring"></div>`, (t) => {
    const st = 23.7 + i * 0.35;
    if (t < st || t > st + 1.6) return null;
    const k = eo(p(t, st, 1.6));
    return { x: CX, y: 720, o: (1 - k) * 0.8, s: 0.5 + k * 1.6 };
  }));
  A(`<img class="logoimg" src="${ICON_SRC}" style="width:330px;height:330px" />`, (t) => {
    if (t < 23.65) return null;
    const k = back(p(t, 23.7, 0.65));
    return { x: CX, y: 720 + Math.sin(t * 2.2) * 6, o: cl(k * 1.6), s: 0.3 + 0.7 * k };
  });
  const wm2 = A(`<img class="logoimg" src="${LOGO_SRC}" style="width:600px;filter:drop-shadow(0 0 36px rgba(46,230,160,0.5))" />`, (t) => {
    if (t < 24.0) return null;
    return { x: CX, y: 975, o: 1 };
  });
  const wm2Img = wm2.querySelector("img");
  subs.push((t) => { wm2Img.style.clipPath = `inset(0 0 0 ${(1 - eo(p(t, 24.0, 0.7))) * 100}%)`; });
  headline("المنصة الإعلامية", { y: 1175, start: 24.55, end: 99, size: 80 });
  headline("الجزائرية الشاملة", { y: 1280, start: 24.9, end: 99, size: 80, hl: ["الجزائرية", "الشاملة"] });
  A(`<div class="url">sanadz.media</div>`, (t) => {
    if (t < 25.5) return null;
    const k = back(p(t, 25.55, 0.55));
    const pulse = 1 + 0.025 * Math.sin((t - 26) * 3.2) * p(t, 26.2, 0.5);
    return { x: CX, y: 1450, o: cl(k * 1.5), s: (0.6 + 0.4 * k) * pulse };
  });

  // ── render ─────────────────────────────────────────────────────────
  const DURATION = 28.0;
  const render = (t) => {
    bg(t);
    for (const { d, fn } of anims) apply(d, fn(t));
    for (const s of subs) s(t);
    // a gentle fade at the very start and end, so the loop is not a hard cut
    stage.style.opacity = Math.min(p(t, 0, 0.25), 1 - p(t, DURATION - 0.35, 0.35));
  };
  const ready = (async () => {
    const faces = ["700 40px Cairo", "800 40px Cairo", "900 40px Cairo", "500 40px Tajawal", "700 40px Tajawal"];
    await Promise.all(faces.flatMap((f) => [document.fonts.load(f, "سند الإعلام"), document.fonts.load(f, "sanadz.media 123…")]));
    await document.fonts.ready;
    await Promise.all([...stage.querySelectorAll("img")].map((im) => (im.complete ? 0 : new Promise((r) => (im.onload = r)))));
    render(0);
    return true;
  })();

  return { render, DURATION, ready };
}

const W = 1080, H = 1920;

export default function SanadReel({ autoPlay = true, loop = true }) {
  const boxRef = useRef(null);
  const stageRef = useRef(null);
  const sceneRef = useRef(null);
  const timeRef = useRef(0);
  const playingRef = useRef(autoPlay);
  const [playing, setPlaying] = useState(autoPlay);
  const [time, setTime] = useState(0);
  const [scale, setScale] = useState(0.3);
  const [ready, setReady] = useState(false);

  // Build the scene once, and run the clock.
  useEffect(() => {
    const stage = stageRef.current;
    stage.innerHTML = STAGE_HTML;
    const scene = buildScene(stage);
    sceneRef.current = scene;
    let raf = 0, last = 0, lastUi = 0, alive = true;

    scene.ready.then(() => {
      if (!alive) return;
      setReady(true);
      const tick = (now) => {
        const dt = last ? (now - last) / 1000 : 0;
        last = now;
        if (playingRef.current) {
          let t = timeRef.current + dt;
          if (t >= scene.DURATION) {
            if (loop) t %= scene.DURATION;
            else { t = scene.DURATION; playingRef.current = false; setPlaying(false); }
          }
          timeRef.current = t;
          scene.render(t);
        }
        if (now - lastUi > 100) { lastUi = now; setTime(timeRef.current); }
        raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
    });

    return () => { alive = false; cancelAnimationFrame(raf); stage.innerHTML = ""; };
  }, [loop]);

  // Fit 1080×1920 into whatever space the component is given.
  useEffect(() => {
    const box = boxRef.current;
    const fit = () => {
      const maxH = Math.min(window.innerHeight * 0.82, H);
      setScale(Math.min(box.clientWidth / W, maxH / H));
    };
    fit();
    const ro = new ResizeObserver(fit);
    ro.observe(box);
    window.addEventListener("resize", fit);
    return () => { ro.disconnect(); window.removeEventListener("resize", fit); };
  }, []);

  const toggle = () => {
    const scene = sceneRef.current;
    if (!scene) return;
    if (!playingRef.current && timeRef.current >= scene.DURATION) timeRef.current = 0;
    playingRef.current = !playingRef.current;
    setPlaying(playingRef.current);
  };

  const seek = (t) => {
    timeRef.current = t;
    sceneRef.current?.render(t);
    setTime(t);
  };

  const fmt = (s) => `0:${String(Math.floor(s)).padStart(2, "0")}`;

  return (
    <div ref={boxRef} className="sr" style={{ width: "100%", display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
      <style>{CSS}</style>
      <div
        onClick={toggle}
        style={{ width: W * scale, height: H * scale, borderRadius: 16, overflow: "hidden", position: "relative", cursor: "pointer", background: "#000", boxShadow: "0 20px 60px rgba(0,0,0,0.5)" }}
      >
        <div ref={stageRef} id="stage" style={{ transform: `scale(${scale})`, transformOrigin: "top left" }} />
        {!ready && (
          <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", color: "#2ee6a0", fontFamily: "sans-serif" }}>
            …
          </div>
        )}
      </div>
      <div dir="ltr" style={{ width: W * scale, display: "flex", alignItems: "center", gap: 12, fontFamily: "system-ui, sans-serif", color: "#cfe9db", fontSize: 13 }}>
        <button
          type="button"
          onClick={toggle}
          aria-label={playing ? "إيقاف مؤقت" : "تشغيل"}
          style={{ width: 38, height: 38, borderRadius: "50%", border: "none", cursor: "pointer", background: "linear-gradient(135deg,#00a355,#2ee6a0)", color: "#fff", fontSize: 15, flexShrink: 0 }}
        >
          {playing ? "❚❚" : "▶"}
        </button>
        <input
          type="range"
          min={0}
          max={28}
          step={0.01}
          value={time}
          onChange={(e) => seek(Number(e.target.value))}
          aria-label="موضع الفيديو"
          style={{ flex: 1, accentColor: "#00a355" }}
        />
        <span style={{ fontVariantNumeric: "tabular-nums", minWidth: 70, textAlign: "right" }}>{fmt(time)} / 0:28</span>
      </div>
    </div>
  );
}
